152:     function addMigratedDepositsToAccount(
153:         address account,
154:         AccountDepositData calldata depositData
155:     ) internal returns (uint256 accountStalk) {
156:         int96 stemTip = LibTokenSilo.stemTipForToken(depositData.token);
157:         uint256 stalkIssuedPerBdv = s.sys.silo.assetSettings[depositData.token].stalkIssuedPerBdv;
158:         uint128 totalBdvForAccount;
159:         uint128 totalDeposited;
160:         uint128 totalDepositedBdv;
161:         for (uint256 i; i < depositData.depositIds.length; i++) {
162:             // verify that depositId is valid.
163:             uint256 depositId = depositData.depositIds[i];
164:             (address depositToken, int96 stem) = depositId.unpackAddressAndStem();
165:             require(depositToken == depositData.token, "Migration: INVALID_DEPOSIT_ID");
166:             require(stemTip >= stem, "Migration: INVALID_STEM");
167: 
168:             // add deposit to account.
169:             s.accts[account].deposits[depositId].amount = depositData.amounts[i];
170:             s.accts[account].deposits[depositId].bdv = depositData.bdvs[i];
171: 
172:             // increment totalBdvForAccount by bdv of deposit:
173:             totalBdvForAccount += depositData.bdvs[i];
174: 
175:             // increment by grown stalk of deposit.
176:             accountStalk += uint96(stemTip - stem) * depositData.bdvs[i];
177: 
178:             // emit events.
179:             emit AddDeposit(
180:                 account,
181:                 depositData.token,
182:                 stem,
183:                 depositData.amounts[i],
184:                 depositData.bdvs[i]
185:             );
186:             emit TransferSingle(msg.sender, address(0), account, depositId, depositData.amounts[i]);
187:         }
188: 
189:         // update mowStatuses for account and token.
190:         s.accts[account].mowStatuses[depositData.token].bdv = totalBdvForAccount;
191:         s.accts[account].mowStatuses[depositData.token].lastStem = stemTip;
192: 
193:         // set global state
194:         s.sys.silo.balances[depositData.token].deposited = totalDeposited;
195:         s.sys.silo.balances[depositData.token].depositedBdv = totalDepositedBdv;
196: 
197:         // increment stalkForAccount by the stalk issued per BDV.
198:         // placed outside of loop for gas effiency.
199:         accountStalk += stalkIssuedPerBdv * totalBdvForAccount;
200:     }
