202:     /**
203:      * @notice increments the stalk and roots for an account.
204:      */
205:     function setStalk(address account, uint256 accountStalk, uint256 accountRoots) internal {
206:         s.accts[account].stalk += accountStalk;
207:         s.accts[account].roots += accountRoots;
208: 
209:         // emit event.
210:         emit StalkBalanceChanged(account, int256(accountStalk), int256(accountRoots));
